{"implementation":"def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    for n in nodes:
        if n not in core:
            raise ValueError(f'Missing core distance for {n}')
    edges = []
    for u, v, d in dist_list:
        w = max(core[u], core[v], d)
        if u <= v:
            a, b = u, v
        else:
            a, b = v, u
        edges.append((w, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append((a, b, w))
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is disconnected')
    mst_edges.sort(key=lambda x: (x[2], x[0], x[1]))
    return {'edges': [[a, b, w] for a,b,w in mst_edges], 'total_weight': total_weight}"}
